  required: (p) => p.missingProperty !== undefined
    ? `필수 속성 '${p.missingProperty}'이(가) 필요합니다`
    : '필수 속성이 필요합니다',
  minimum: (p) => `${p.comparison} ${num(p.limit)} 이어야 합니다`,
  maximum: (p) => `${p.comparison} ${num(p.limit)} 이어야 합니다`,
